output-exprs.el:
errorServicio:if(
  and(
    a!isNotNullOrEmpty(pv!mensajes),
    length(pv!mensajes) > 0
  ),
  if(
    and(
      a!isNotNullOrEmpty(pv!mensajes[1].codigo),
      pv!mensajes[1].codigo <> "1001"
    ),
    pv!mensajes[0].descripcion,
    pv!errorServicio
  ),
  pv!errorServicio
)

uiExpressionForm.expression:
=/*41707069616E-GEN-DEBUG*/=a!formLayout(
  buttons: a!buttonLayout(
    primaryButtons: {
      a!buttonWidgetSubmit(
        label: "OK",
        style: "PRIMARY"
      )
    }
  ))
